/* Modal on frosted glass, the popover and toast
   family at reading weight: a touch more opaque than a menu (0.86 against
   0.72) because people read a whole form in here, with a stronger blur.
   Depth comes from shadows above and below plus a white specular top edge,
   never an outline. The tone is a soft wash washed in from the icon side
   and a soft icon tile, never a fill or a side bar.

   Every surface value is a --modal-* token, so the flat preset turns it
   into the flat flat white square with a hairline, a neutral scrim and
   no blur, without a selector here. Width, radius and padding are
   per-component tokens too (--modal-width-sm|md|lg, --modal-radius,
   --modal-radius-lg, --modal-pad-x). Widths: sm 480, md 640, lg 880
  . */

.root {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.root[data-state="closed"] {
  pointer-events: none;
}

/* ── Scrim: the page recedes under a deep veil ─────────────────────────
   Deeper at the edges than behind the panel so the eye settles on the
   dialog; the blur takes the page's detail away without hiding where you
   are. Flat: a flat neutral veil, no blur. */
.scrim {
  position: absolute;
  inset: 0;
  background: var(--modal-scrim);
  -webkit-backdrop-filter: var(--modal-scrim-blur);
  backdrop-filter: var(--modal-scrim-blur);
  animation: scrim-in 240ms var(--ease) both;
}

.root[data-state="closed"] .scrim {
  animation: scrim-out 200ms var(--ease) forwards;
}

/* ── Panel ───────────────────────────────────────────────────────────── */

.panel {
  --_pad-x: var(--modal-pad-x, calc(24px * var(--density)));

  /* Tone channels. Default is the brand gesture, barely there. */
  --tone-color: rgb(var(--rgb-brand));
  --tone-ink: var(--ink-brand);
  --tone-bar: var(--brand-gradient);
  --tone-wash: 7%;
  --tone-tile: 12%;

  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-height: min(calc(100dvh - 48px), 880px);
  overflow: hidden;
  background: var(--modal-surface);
  -webkit-backdrop-filter: var(--modal-blur);
  backdrop-filter: var(--modal-blur);
  border-radius: var(--modal-radius, var(--r-xl));
  box-shadow: var(--modal-shadow);
  outline: none;
  transform-origin: 50% 60%;
  animation: panel-in 320ms var(--ease-out) both;
}

.root[data-state="closed"] .panel {
  animation: panel-out 180ms var(--ease) forwards;
}

.sm {
  max-width: var(--modal-width-sm, 480px);
}

.md {
  max-width: var(--modal-width-md, 640px);
}

/* The widest panel takes the page-level radius: the scale tracks size. */
.lg {
  max-width: var(--modal-width-lg, 880px);
  border-radius: var(--modal-radius-lg, var(--r-2xl));
}

.tone-danger {
  --tone-color: rgb(var(--rgb-danger));
  --tone-ink: var(--danger-ink);
  --tone-bar: var(--danger-gradient);
  /* Warnings carry a clearly red header bloom. */
  --tone-wash: 26%;
  --tone-tile: 13%;
}

.tone-success {
  --tone-color: var(--success-solid);
  --tone-ink: var(--success-ink);
  --tone-bar: var(--success-gradient);
  --tone-wash: 24%;
  --tone-tile: 12%;
}

.tone-info {
  --tone-color: rgb(var(--rgb-brand-soft));
  --tone-ink: var(--info-ink);
  --tone-wash: 12%;
  --tone-tile: 18%;
}

/* The tone wash: a soft light from the tile's corner, gone by the body.
   Behind everything, clipped by the panel's radius. Flat: off. */
.wash {
  position: absolute;
  inset: 0 0 auto;
  height: 200px;
  pointer-events: none;
  /* Two soft layers: a broad light from the tile's corner and a gentler
     sweep across the header, both gone before the body text. */
  background:
    radial-gradient(
      120% 100% at 0% 0%,
      color-mix(in srgb, var(--tone-color) var(--tone-wash), transparent) 0%,
      transparent 72%
    ),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--tone-color) calc(var(--tone-wash) * 0.45), transparent) 0%,
      transparent 100%
    );
  opacity: var(--modal-wash-opacity);
  transition: opacity 300ms var(--ease);
}

/* ── Header ──────────────────────────────────────────────────────────── */

.header {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  padding: calc(22px * var(--density)) calc(16px * var(--density)) calc(18px * var(--density)) var(--_pad-x);
  transition: box-shadow 200ms var(--ease);
}

/* Scroll-aware: a hairline and a short soft shade once the body has moved
   under the header. None while the content sits at the top. */
.panel[data-scrolled] .header {
  box-shadow: var(--scroll-edge-top);
}

/* One left edge for everything: the icon tile sits on
   its own row with the close button, and the eyebrow, title and description
   run full width beneath it, flush with the body text. Without a tile the
   heading and close share the first row. */
.headerRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  column-gap: 14px;
  row-gap: 14px;
}

.headerRow .heading {
  grid-column: 1;
  grid-row: 1;
}

.headerRow:has(.tile) .heading {
  grid-column: 1 / -1;
  grid-row: 2;
}

.headerRow .tile {
  grid-column: 1;
  grid-row: 1;
  justify-self: start;
}

/* Soft tile: a light wash of the tone, the icon in the tone's ink, a white
   specular edge and a faint tone ring. No gradient fill, no glow. */
.tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: var(--r-md);
  color: var(--tone-ink);
  background: color-mix(in srgb, var(--tone-color) var(--tone-tile), transparent);
  box-shadow:
    var(--shadow-specular),
    inset 0 0 0 1px color-mix(in srgb, var(--tone-color) 18%, transparent);
  transition:
    color 300ms var(--ease),
    background-color 300ms var(--ease);
}

.heading {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding-top: 1px;
  animation: heading-in 260ms var(--ease-out) both;
}

/* A quiet line under the title (a reference, "Step 1 of 2"), never a label
   stacked over it. */
.meta {
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-muted);
}

.title {
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 400;
  letter-spacing: var(--tracking-display);
  line-height: 1.25;
  color: var(--ink-heading);
  text-wrap: balance;
  overflow-wrap: anywhere;
}

.description {
  margin-top: 2px;
  font-size: var(--text-small);
  line-height: 1.55;
  color: var(--ink-secondary);
  text-wrap: pretty;
}

/* IconButton ghost, pulled up and out so its glyph sits on the title's
   cap line and its hit area reaches the corner. */
.close {
  grid-column: 2;
  grid-row: 1;
  margin: -6px -4px 0 0;
}

/* With a tile, centre the close button on the tile rather than the title. */
.headerRow:has(.tile) .close {
  align-self: center;
  margin: 0 -4px 0 0;
}

/* Step rule: one segment per step, filled up to the current one. the reference design's
   invoice dialog, thinned to a hairline weight. */
.progress {
  display: flex;
  gap: 4px;
  margin-top: 16px;
}

.segment {
  flex: 1;
  height: 3px;
  border-radius: var(--r-full);
  background: rgba(var(--rgb-brand-deep), 0.1);
  transition: background 320ms var(--ease);
}

.segment[data-done] {
  background: var(--tone-bar);
}

/* ── Body ────────────────────────────────────────────────────────────── */

.body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 4px var(--_pad-x) calc(22px * var(--density));
  font-size: var(--text-body);
  line-height: 1.6;
  color: var(--ink-body);
  /* overscroll-behavior and the thin tinted scrollbar: Scroll's .themed,
     composed in Modal.tsx so every scroller shares one recipe. */
}

.body:focus-visible {
  outline: none;
}

.content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Text uses the panel's full width; balanced breaks instead. */
.content > p {
  text-wrap: pretty;
}

/* ConfirmModal's step: cross-fades in the direction of travel. */
.step {
  display: flex;
  flex-direction: column;
  gap: 16px;
  outline: none;
  animation: step-in 280ms var(--ease-out) both;
}

.step[data-direction="back"] {
  animation-name: step-in-back;
}

/* ── Footer ──────────────────────────────────────────────────────────── */

.footer {
  position: relative;
  z-index: 1;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 12px;
  padding: calc(14px * var(--density)) var(--_pad-x) calc(20px * var(--density));
  transition: box-shadow 200ms var(--ease);
}

/* Scroll-aware: shows only while there is more content below. */
.panel[data-more] .footer {
  box-shadow: var(--scroll-edge-bottom);
}

.footerStart {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin-left: -8px; /* a ghost Back button's label lines up with the body text */
  font-size: var(--text-small);
  line-height: 1.45;
  color: var(--ink-secondary);
}

/* Plain text on the left (not a button) sits on the body's edge. */
.footerStart:not(:has(> button, > a[class])) {
  margin-left: 0;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  margin-left: auto;
}

/* ── Mobile: a bottom sheet ───────────────────────────────────────────
   Every size slides up from the bottom edge under 640px, square at the
   foot, rounded at the head. fullscreen takes the whole viewport for long
   forms. Actions stack full width, primary last, nearest the thumb. */
@media (max-width: 639px) {
  .root {
    align-items: flex-end;
    padding: 12px 0 0;
  }

  .panel,
  .lg {
    max-width: none;
    max-height: calc(100dvh - 12px);
    border-radius: var(--r-2xl) var(--r-2xl) 0 0;
    transform-origin: 50% 100%;
    animation-name: sheet-in;
    animation-duration: 360ms;
  }

  .root[data-state="closed"] .panel {
    animation-name: sheet-out;
    animation-duration: 200ms;
  }

  .fullscreen {
    height: 100dvh;
    max-height: 100dvh;
    border-radius: 0;
  }

  .root:has(.fullscreen) {
    padding: 0;
  }

  .header {
    padding: 20px 12px 16px 20px;
  }

  .body {
    padding: 4px 20px 20px;
  }

  .footer {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding: 14px 20px max(20px, calc(env(safe-area-inset-bottom) + 12px));
  }

  .footerStart {
    margin-left: 0;
  }

  .footerStart > * {
    width: 100%;
  }

  .actions {
    flex-direction: column;
    margin-left: 0;
  }

  .actions > * {
    width: 100%;
  }
}

/* ── Motion ──────────────────────────────────────────────────────────── */

@keyframes scrim-in {
  from {
    opacity: 0;
  }
}

@keyframes scrim-out {
  to {
    opacity: 0;
  }
}

/* Entrance only: a 12px rise and a settle from 0.98. Never on hover. */
@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
}

@keyframes panel-out {
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.985);
  }
}

@keyframes sheet-in {
  from {
    transform: translateY(100%);
  }
}

@keyframes sheet-out {
  to {
    transform: translateY(100%);
  }
}

@keyframes heading-in {
  from {
    opacity: 0;
  }
}

@keyframes step-in {
  from {
    opacity: 0;
    transform: translateX(12px);
  }
}

@keyframes step-in-back {
  from {
    opacity: 0;
    transform: translateX(-12px);
  }
}

@keyframes fade-only {
  from {
    opacity: 0;
  }
}

@keyframes fade-only-out {
  to {
    opacity: 0;
  }
}

/* Reduced motion: everything fades in place, nothing travels or scales. */
@media (prefers-reduced-motion: reduce) {
  .panel,
  .step,
  .step[data-direction="back"],
  .heading {
    animation: fade-only 140ms linear both;
  }

  .root[data-state="closed"] .panel {
    animation: fade-only-out 140ms linear forwards;
  }

  .scrim {
    animation: fade-only 140ms linear both;
  }

  .root[data-state="closed"] .scrim {
    animation: fade-only-out 140ms linear forwards;
  }
}

/* Inline: the open panel in normal flow, for docs and thumbnails. No entry
   animation, no viewport clamp, a fixed reading width. */
.inline {
  width: var(--modal-inline-width, 520px);
  max-width: 100%;
  max-height: none;
  animation: none;
}

.inline.lg {
  width: var(--modal-inline-width-lg, 640px);
}

.inline .heading,
.inline .step {
  animation: none;
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { cx } from "../_internal/cx";
import { Portal, useIsClient } from "../_internal/portal";
import { focusableWithin } from "../_internal/position";
import { useScrollLock } from "../Scroll/scroll-lock";
import { themedScrollClass } from "../Scroll/ScrollArea";
import { useScrollEdges } from "../Scroll/useScrollEdges";
import { Button } from "../Button/Button";
import { IconAlertTriangle, IconArrowLeft, IconCheckCircle, IconInfo, IconX } from "../Icon/Icon";
import { IconButton } from "../IconButton/IconButton";
import styles from "./Modal.module.css";

export type ModalTone = "default" | "danger" | "success" | "info";

export type ModalProps = {
  open: boolean;
  /** Called on Esc, scrim click and the close button, unless dismissible is false. */
  onClose: () => void;
  title: ReactNode;
  /** A quiet line under the title: a reference, "Step 1 of 2". Never stacked over the title. */
  meta?: ReactNode;
  description?: ReactNode;
  children?: ReactNode;
  /**
   * Render the open panel in place, in normal flow: no portal, no scrim, no
   * inert page, no scroll lock, no focus trap and no exit animation. For
   * docs, thumbnails and design reviews, where many can render at once.
   */
  inline?: boolean;
  /** Buttons, right-aligned. Primary last, and one gradient primary at most. */
  footer?: ReactNode;
  /** Left side of the footer: a line of secondary text, a link, a Back button. */
  footerStart?: ReactNode;
  /** sm 480, md 640, lg 880 (--modal-width-*). Under 640px every size becomes a bottom sheet. */
  size?: "sm" | "md" | "lg";
  /** Under 640px: a bottom sheet (default) or the full screen, for long forms. */
  mobile?: "sheet" | "fullscreen";
  /** Tints the header wash and the icon tile. danger, success and info bring
      their own icon; pass icon={false} to drop it. */
  tone?: ModalTone;
  icon?: ReactNode;
  /** A multi-step flow: draws the segmented step rule under the heading. */
  progress?: { step: number; of: number };
  /**
   * Called when the body has been scrolled to its end (and at once if it
   * does not overflow). Gate a terms "Accept" on it: see the scroll-gated
   * accept example.
   */
  onScrollEnd?: () => void;
  /** false while a request is in flight: Esc, scrim and close are ignored. */
  dismissible?: boolean;
  /** A request is in flight: sets aria-busy and locks dismissal. */
  busy?: boolean;
  /** Focused on open. Defaults to the first field or button in the body. */
  initialFocus?: RefObject<HTMLElement | null>;
  closeLabel?: string;
  className?: string;
};

// Long enough for the exit animation (180ms panel, 200ms scrim) to finish.
const EXIT_MS = 210;

const TONE_ICON: Record<ModalTone, ReactNode> = {
  default: null,
  danger: <IconAlertTriangle size={19} />,
  success: <IconCheckCircle size={19} />,
  info: <IconInfo size={19} />,
};

// ── Inert background ─────────────────────────────────────────────────────
// Everything beside the dialog in <body> goes inert, so neither a screen
// reader's virtual cursor nor a stray click reaches the page. The toast
// region stays live: a modal that stays open after a failed request says so
// with a toast (WithdrawModal), and an inert live region is never announced.
// Popups opened from inside the modal (Select, DateField) portal in after
// this runs and are untouched.
const KEEP_LIVE = 'section[aria-label="Notifications"], [aria-live], [role="alert"], [role="status"], next-route-announcer';

function inertSiblings(root: HTMLElement): HTMLElement[] {
  const changed: HTMLElement[] = [];
  for (const el of Array.from(document.body.children)) {
    if (!(el instanceof HTMLElement) || el === root || el.contains(root)) continue;
    if (el.hasAttribute("inert") || el.matches(KEEP_LIVE)) continue;
    el.setAttribute("inert", "");
    changed.push(el);
  }
  return changed;
}

// Open modals, newest last. Only the top one answers Esc and traps Tab when
// focus has fallen out to <body> (a click on the scrim does that).
const stack: HTMLElement[] = [];

/**
 * Portalled dialog on frosted glass: focus trap, Esc, scrim click, scroll
 * lock, an inert background, and focus returned to whatever opened it.
 * Stays mounted for its exit animation after open turns false.
 */
export function Modal(props: ModalProps) {
  const { open } = props;
  const [present, setPresent] = useState(open);
  const [prevOpen, setPrevOpen] = useState(open);
  if (open !== prevOpen) {
    setPrevOpen(open);
    if (open) setPresent(true);
  }

  useEffect(() => {
    if (open || !present) return;
    const t = window.setTimeout(() => setPresent(false), EXIT_MS);
    return () => window.clearTimeout(t);
  }, [open, present]);

  if (props.inline) return open ? <ModalFrame {...props} /> : null;
  if (!present) return null;
  return <ModalFrame {...props} />;
}

function ModalFrame({
  open,
  onClose,
  title,
  meta,
  description,
  children,
  footer,
  footerStart,
  inline = false,
  size = "md",
  mobile = "sheet",
  tone = "default",
  icon,
  progress,
  onScrollEnd,
  dismissible = true,
  busy = false,
  initialFocus,
  closeLabel = "Close",
  className,
}: ModalProps) {
  const titleId = useId();
  const descId = useId();
  // Portal renders nothing until hydration; effects wait for the real nodes.
  const isClient = useIsClient();
  const hasBody = Boolean(children);
  const rootRef = useRef<HTMLDivElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const bodyRef = useRef<HTMLDivElement>(null);
  const openerRef = useRef<HTMLElement | null>(null);
  // A press that starts inside the panel and ends on the scrim (selecting
  // text, dragging a slider) must not close the dialog.
  const pressOnScrim = useRef(false);

  const canDismiss = dismissible && !busy && open;
  // The document listener below is bound once per opening; it reads these.
  const dismissRef = useRef({ canDismiss, onClose });
  useEffect(() => {
    dismissRef.current = { canDismiss, onClose };
  });

  // Scroll lock spans the whole mount, exit animation included, so the
  // scrollbar does not come back under a panel that is still fading. The
  // counter is shared (components/ui/Scroll), so nested overlays nest.
  useScrollLock(!inline);

  // Per opening: inert the page, move focus in, trap it; on close (or an
  // abrupt unmount) release the page first, then hand focus back.
  useEffect(() => {
    if (!open || !isClient || inline) return;
    const root = rootRef.current;
    const dialog = dialogRef.current;
    if (!root || !dialog) return;

    openerRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const released = inertSiblings(root);
    stack.push(dialog);

    const target =
      initialFocus?.current ??
      (bodyRef.current ? focusableWithin(bodyRef.current)[0] : undefined) ??
      focusableWithin(dialog).find((el) => !el.dataset.modalClose) ??
      dialog;
    target.focus({ preventScroll: true });

    const onDocKeyDown = (e: globalThis.KeyboardEvent) => {
      if (stack[stack.length - 1] !== dialog) return;
      // Only when focus has fallen out to <body>. Keys from the dialog are
      // handled on it, and a portalled popup inside it (a calendar) stops
      // its own Esc in React, which does not stop a native document listener.
      if (e.target !== document.body && e.target !== document.documentElement) return;
      if (e.key === "Escape") {
        if (dismissRef.current.canDismiss) dismissRef.current.onClose();
      } else if (e.key === "Tab") {
        e.preventDefault();
        const items = focusableWithin(dialog);
        (e.shiftKey ? items[items.length - 1] : items[0])?.focus();
      }
    };
    document.addEventListener("keydown", onDocKeyDown);

    return () => {
      document.removeEventListener("keydown", onDocKeyDown);
      const i = stack.lastIndexOf(dialog);
      if (i >= 0) stack.splice(i, 1);
      for (const el of released) el.removeAttribute("inert");
      const opener = openerRef.current;
      if (opener && opener.isConnected) opener.focus({ preventScroll: true });
    };
    // initialFocus is read once, on open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, isClient]);

  // Scroll-aware dividers: a hairline under the header once the body has
  // scrolled, and one over the footer while there is more below. Written
  // straight to the panel's dataset so scrolling never re-renders.
  useScrollEdges(bodyRef, { target: dialogRef, enabled: hasBody && isClient, onEnd: onScrollEnd });

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!open || inline) return;
    if (e.key === "Escape") {
      e.stopPropagation();
      if (canDismiss) onClose();
      return;
    }
    if (e.key !== "Tab" || !dialogRef.current) return;
    const items = focusableWithin(dialogRef.current);
    if (items.length === 0) {
      e.preventDefault();
      return;
    }
    const first = items[0];
    const last = items[items.length - 1];
    if (e.shiftKey && (document.activeElement === first || document.activeElement === dialogRef.current)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };

  const onScrimDown = (e: MouseEvent<HTMLDivElement>) => {
    pressOnScrim.current = e.target === e.currentTarget;
  };
  const onScrimClick = (e: MouseEvent<HTMLDivElement>) => {
    const fromScrim = pressOnScrim.current && e.target === e.currentTarget;
    pressOnScrim.current = false;
    if (fromScrim && canDismiss) onClose();
  };

  const tile = icon ?? TONE_ICON[tone];
  const toneClass = tone === "default" ? undefined : styles[`tone-${tone}`];

  const panel = (
    <div data-slot="modal"
      ref={dialogRef}
      role={tone === "danger" ? "alertdialog" : "dialog"}
      aria-modal={inline ? undefined : "true"}
      aria-labelledby={titleId}
      aria-describedby={description ? descId : undefined}
      aria-busy={busy || undefined}
      tabIndex={inline ? undefined : -1}
      data-surface="solid"
      className={cx(
        styles.panel,
        styles[size],
        mobile === "fullscreen" && styles.fullscreen,
        inline && styles.inline,
        toneClass,
        className,
      )}
      onKeyDown={onKeyDown}
    >
      <span className={styles.wash} aria-hidden="true" />
      <header className={styles.header}>
        <div className={styles.headerRow}>
          {tile ? (
            <span className={styles.tile} aria-hidden="true">
              {tile}
            </span>
          ) : null}
          {/* Re-keyed per step so a two-step flow cross-fades its heading. */}
          <div key={progress?.step ?? 0} className={styles.heading}>
            <h2 id={titleId} className={styles.title}>
              {title}
            </h2>
            {meta ? <p className={styles.meta}>{meta}</p> : null}
            {description ? (
              <p id={descId} className={styles.description}>
                {description}
              </p>
            ) : null}
          </div>
          <IconButton
            icon={<IconX size={18} />}
            label={closeLabel}
            variant="ghost"
            className={styles.close}
            onClick={onClose}
            disabled={!canDismiss}
            data-modal-close="true"
          />
        </div>
        {progress && progress.of > 1 ? (
          <div className={styles.progress} aria-hidden="true">
            {Array.from({ length: progress.of }, (_, i) => (
              <span key={i} className={styles.segment} data-done={i < progress.step || undefined} />
            ))}
          </div>
        ) : null}
      </header>
      {hasBody ? (
        <div ref={bodyRef} className={cx(styles.body, themedScrollClass)}>
          {/* The observed box: it grows with the content (an error
              appearing, a step changing) while the body stays clamped. */}
          <div className={styles.content}>{children}</div>
        </div>
      ) : null}
      {footer || footerStart ? (
        <footer className={styles.footer}>
          {footerStart ? <div className={styles.footerStart}>{footerStart}</div> : null}
          {footer ? <div className={styles.actions}>{footer}</div> : null}
        </footer>
      ) : null}
    </div>
  );

  if (inline) return panel;

  return (
    <Portal>
      <div ref={rootRef} className={styles.root} data-state={open ? "open" : "closed"}>
        <div className={styles.scrim} aria-hidden="true" onMouseDown={onScrimDown} onClick={onScrimClick} />
        {panel}
      </div>
    </Portal>
  );
}

export type ConfirmModalProps = {
  open: boolean;
  onClose: () => void;
  title: ReactNode;
  /** A quiet line under the title; two-step flows prefix it with "Step 1 of 2". */
  meta?: string;
  description?: ReactNode;
  /** Render the open dialog in place (see Modal's inline). */
  inline?: boolean;
  /** Step one: the details or form (e.g. withdrawal reason). */
  children?: ReactNode;
  /**
   * Step two: what will happen, stated plainly. When given, the first button
   * reads proceedLabel and leads here; the destructive button is only on
   * this step. Omit for a single-step confirm.
   */
  review?: ReactNode;
  reviewTitle?: ReactNode;
  /** Replaces description on step two. Omitted: step two has none. */
  reviewDescription?: ReactNode;
  proceedLabel?: string;
  confirmLabel: string;
  cancelLabel?: string;
  tone?: ModalTone;
  /** Overrides the tone's icon tile; false drops it. */
  icon?: ReactNode;
  /** Return false to stay on step one (failed validation). */
  onProceed?: () => boolean;
  onConfirm: () => void;
  /** The confirm request is in flight. Locks the dialog. */
  busy?: boolean;
  busyLabel?: string;
  size?: ModalProps["size"];
  mobile?: ModalProps["mobile"];
};

/**
 * The two-step confirm: fill in, then review and confirm. The
 * irreversible button never appears on the same screen as the inputs that
 * feed it, so a stray Enter cannot confirm a destructive action.
 *
 * One dialog throughout: the step rule fills, the heading and body
 * cross-fade in the direction of travel, and a danger flow keeps its tile
 * on both steps so nothing jumps. Only step two carries the danger button.
 */
export function ConfirmModal({
  open,
  onClose,
  title,
  meta,
  description,
  inline,
  children,
  review,
  reviewTitle,
  reviewDescription,
  proceedLabel = "Continue",
  confirmLabel,
  cancelLabel = "Cancel",
  tone = "default",
  icon,
  onProceed,
  onConfirm,
  busy,
  busyLabel,
  size = "md",
  mobile,
}: ConfirmModalProps) {
  const twoStep = review !== undefined;
  const [step, setStep] = useState<1 | 2>(1);
  const [direction, setDirection] = useState<"forward" | "back">("forward");
  // Each opening starts on step one. Reset while rendering, not in an
  // effect, so the first frame of a reopened dialog is already step one.
  const [wasOpen, setWasOpen] = useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) {
      setStep(1);
      setDirection("forward");
    }
  }

  const onReview = twoStep && step === 2;
  const stepRef = useRef<HTMLDivElement>(null);
  // Set only by Back and Continue, so the reset on reopening never pulls
  // focus away from the field the dialog focused on open.
  const focusStep = useRef(false);

  // The button that changed the step has unmounted; put focus on the new content.
  useEffect(() => {
    if (!focusStep.current) return;
    focusStep.current = false;
    stepRef.current?.focus({ preventScroll: true });
  }, [step]);

  const go = (to: 1 | 2) => {
    focusStep.current = true;
    setDirection(to > step ? "forward" : "back");
    setStep(to);
  };

  const footerStart = onReview ? (
    <Button variant="ghost" iconStart={<IconArrowLeft size={15} />} onClick={() => go(1)} disabled={busy}>
      Back
    </Button>
  ) : null;

  const footer = (
    <>
      <Button variant="secondary" onClick={onClose} disabled={busy}>
        {cancelLabel}
      </Button>
      {twoStep && step === 1 ? (
        <Button
          variant={tone === "danger" ? "dangerSecondary" : "primary"}
          onClick={() => {
            if (!onProceed || onProceed()) go(2);
          }}
        >
          {proceedLabel}
        </Button>
      ) : (
        <Button variant={tone === "danger" ? "danger" : "primary"} onClick={onConfirm} loading={busy} loadingLabel={busyLabel}>
          {confirmLabel}
        </Button>
      )}
    </>
  );

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={onReview ? (reviewTitle ?? title) : title}
      meta={twoStep ? `Step ${step} of 2${meta ? ` · ${meta}` : ""}` : meta}
      inline={inline}
      description={onReview ? reviewDescription : description}
      tone={tone}
      icon={icon}
      progress={twoStep ? { step, of: 2 } : undefined}
      busy={busy}
      size={size}
      mobile={mobile}
      footer={footer}
      footerStart={footerStart}
    >
      <div key={step} ref={stepRef} tabIndex={-1} className={styles.step} data-direction={direction}>
        {onReview ? review : children}
      </div>
    </Modal>
  );
}
